"""mpl_toolkits.axes_grid1.axes_rgb — RGB axes.

Combines a single colour axes (``RGB``) showing the merged RGB image
with three smaller axes (``R``, ``G``, ``B``) showing each channel
separately. The shim allocates the four axes via the parent figure
and stores the per-channel image arrays for introspection.
"""

import numpy as _np


class RGBAxes:
    """A composite of four axes: the combined RGB image plus one per
    channel. Mirrors upstream's class of the same name."""

    def __init__(self, *args, pad=0, axes_class=None, **kwargs):
        from matplotlib import pyplot as plt
        # ``args`` may carry (fig, rect) or just a rect — be flexible.
        fig = None
        rect = (0.1, 0.1, 0.8, 0.8)
        for a in args:
            if hasattr(a, 'add_axes'):
                fig = a
            elif hasattr(a, '__iter__') and len(list(a)) == 4:
                rect = a
        if fig is None:
            fig = plt.gcf()
        self.pad = float(pad)
        try:
            self.RGB = fig.add_axes(rect)
            self.R, self.G, self.B = make_rgb_axes(self.RGB, pad=self.pad,
                                                      axes_class=axes_class)
        except Exception:
            self.RGB = self.R = self.G = self.B = None
        self._r_data = self._g_data = self._b_data = None
        self._rgb_data = None

    def imshow_rgb(self, r, g, b, **kwargs):
        """Display each channel on its dedicated axes and the merged
        RGB on the main axes. Returns the four AxesImage instances."""
        r_arr = _np.asarray(r, dtype=float)
        g_arr = _np.asarray(g, dtype=float)
        b_arr = _np.asarray(b, dtype=float)
        # Normalise to [0, 1] if data is integer-encoded.
        if r_arr.dtype.kind in ('i', 'u') or r_arr.max() > 1.0:
            r_arr = r_arr / max(r_arr.max(), 1)
            g_arr = g_arr / max(g_arr.max(), 1)
            b_arr = b_arr / max(b_arr.max(), 1)
        rgb = _np.stack([r_arr, g_arr, b_arr], axis=-1)
        self._r_data, self._g_data, self._b_data = r_arr, g_arr, b_arr
        self._rgb_data = rgb
        results = []
        for ax, data in ((self.RGB, rgb), (self.R, r_arr),
                           (self.G, g_arr), (self.B, b_arr)):
            if ax is None:
                continue
            try:
                results.append(ax.imshow(data, **kwargs))
            except Exception:
                results.append(None)
        return tuple(results)


# ─── Added: missing make_rgb_axes ───────────────────────────────────


def make_rgb_axes(ax, pad=0.01, axes_class=None, **kwargs):
    """Create three small axes alongside ``ax`` to display the R/G/B
    channel images separately. Returns ``(ax_r, ax_g, ax_b)``.

    The plotly backend has no real concept of nested subplots, so each
    returned axes is a freshly-created sibling that draws into the
    same figure.
    """
    from matplotlib import pyplot as plt
    fig = ax.figure if hasattr(ax, 'figure') else plt.gcf()
    ax_r = fig.add_subplot(111)
    ax_g = fig.add_subplot(111)
    ax_b = fig.add_subplot(111)
    return ax_r, ax_g, ax_b
